2. Implement LocalUserGate extension:
```typescript
// LocalUserGate.ts
import { createExtension } from '@aspect/xmlui';

interface LocalUserState {
  kind: 'bootstrapping' | 'needs-setup' | 'ready';
  user: User | null;
}

interface User {
  id: number;
  name: string;
  username: string;
  preferences: UserPreferences;
}

export const LocalUserGate = createExtension({
  name: 'LocalUserGate',

  setup() {
    const state = ref<LocalUserState>({ kind: 'bootstrapping', user: null });

    const checkBootstrap = async () => {
      try {
        const response = await fetch('/api/user/bootstrap');
        const data = await response.json();

        if (data.setup_complete && data.user) {
          state.value = { kind: 'ready', user: data.user };
        } else {
          state.value = { kind: 'needs-setup', user: null };
        }
      } catch (error) {
        console.error('Bootstrap check failed:', error);
        state.value = { kind: 'needs-setup', user: null };
      }
    };

    const createUser = async (name: string, username: string) => {
      const response = await fetch('/api/user/bootstrap', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name, username }),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.message);
      }

      const user = await response.json();
      state.value = { kind: 'ready', user };
      return user;
    };

    const updateUser = async (updates: Partial<User>) => {
      const response = await fetch('/api/user/me', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(updates),
      });

      const user = await response.json();
      state.value = { kind: 'ready', user };
      return user;
    };

    // Check on mount
    onMounted(() => checkBootstrap());

    return {
      value: state,
      createUser,
      updateUser,
      refresh: checkBootstrap,
    };
  },
});
```

